export function inspectStructuralLockOrder(source, rule) {
  const [file, label, start, end, markers] = rule;
  const from = source.indexOf(start);
  const to = source.indexOf(end, from + start.length);
  if (from < 0 || to <= from) return [`${file}: missing ${label} boundaries`];
  const body = spaced(source.slice(from, to));
  let previous = -1;
  for (const marker of markers) {
    const current = body.indexOf(spaced(marker));
    if (current < 0 || current <= previous) return [`${file}: invalid ${label}: ${marker}`];
    previous = current;
  }
  return [];
}

export function inspectWiring(source, rule) {
  const [file, label, start, end, marker] = rule;
  const from = source.indexOf(start);
  const to = end === null ? source.length : source.indexOf(end, from + start.length);
  if (from < 0 || to <= from) return [`${file}: missing ${label} boundaries`];
  return containsMarker(source.slice(from, to), marker) ? [] : [`${file}: missing ${label}`];
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const root = process.env.RUSTOK_VERIFY_REPO_ROOT || fileURLToPath(new URL('../../', import.meta.url));
  const errors = WIRING_RULES.flatMap(rule => inspectWiring(readFileSync(path.join(root, rule[0]), 'utf8'), rule));
  errors.push(...STRUCTURAL_LOCK_RULES.flatMap(rule => inspectStructuralLockOrder(readFileSync(path.join(root, rule[0]), 'utf8'), rule)));
  if (errors.length) { console.error(errors.join('\n')); process.exitCode = 1; }
  else console.log(`Forum injected Taxonomy capability reaches ${WIRING_RULES.length} bounded composition edges and ${STRUCTURAL_LOCK_RULES.length} structural lock orders (source only; host adapter runtime verification still required).`);
}
